// Spatial Locality: Caching benefits from adjacent access
const int N = 256;
int matrix[N][N];

void good_locality() {
    // High Cache Hits (Row-major: sequential memory access)
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            matrix[i][j] *= 2; // Accesses contiguous data
        }
    }
}

void poor_locality() {
    // High Cache Misses (Column-major: large stride N)
    for (int j = 0; j < N; ++j) {
        for (int i = 0; i < N; ++i) {
            matrix[i][j] *= 2; // Jumps N elements between accesses
        }
    }
}
